(()=>{'use strict';const D={"ko": {"briefing": {"title": "11월 28일 아침 브리핑: 반등한 시장, 남아 있는 생활의 비용", "intro": "한국과 미국 증시가 반등했지만 가계의 가처분소득까지 함께 늘어난 것은 아니다. 정치권은 개혁과제의 집행, 당내 징계, 대법원장 탄핵 일정을 놓고 갈등을 이어간다. 토요일 아침에는 전날의 종가와 오늘의 일정, 결정과 주장을 분리해 읽는다.", "href": "2026-11-28-morning-briefing-ko.html"}, "history": {"title": "1943년 11월 28일, 지도보다 먼저 움직인 협상", "intro": "1943년 11월 28일 테헤란에서 루스벨트·처칠·스탈린이 만났다. 미국 국무부 역사국은 회담 기간을 11월 28일부터 12월 1일까지로 기록한다. 전쟁을 어떻게 끝낼 것인지와 그 뒤 세계를 어떻게 다룰 것인지가 같은 협상장에 놓였다. 오늘의 국경을 회담 한 번의 결과로 압축하기 전에 결정의 여러 단계를 볼 필요가 있다.", "href": "2026-11-28-tehran-map-before-border-ko.html"}}, "en": {"briefing": {"title": "28 November morning briefing: markets rebound, household costs remain", "intro": "Korean and US shares rebounded, but household disposable income did not rise with them. Politics remains focused on reform implementation, party discipline and a proposed impeachment timetable. On Saturday morning, distinguish yesterday's closes from today's plans, and decisions from demands.", "href": "2026-11-28-morning-briefing-en.html"}, "history": {"title": "November 28, 1943: negotiations moved before the map", "intro": "Roosevelt, Churchill and Stalin met in Tehran on November 28, 1943. The US Office of the Historian dates the conference from November 28 to December 1. How to end the war and how to shape the world afterward shared the negotiating table. Before reducing today's borders to a single conference, we should examine the stages of decision-making.", "href": "2026-11-28-tehran-map-before-border-en.html"}}, "ja": {"briefing": {"title": "11月28日朝のブリーフィング：反発する市場、残る家計の負担", "intro": "韓国と米国の株式市場は反発したが、家計の可処分所得が同じように増えたわけではない。政治では改革の実行、党内処分、最高裁長官の弾劾日程をめぐる対立が続く。土曜の朝は、前日の終値と今日の予定、決定と主張を分けて読む。", "href": "2026-11-28-morning-briefing-ja.html"}, "history": {"title": "1943年11月28日、地図より先に動いた交渉", "intro": "1943年11月28日、ルーズベルト、チャーチル、スターリンがテヘランで会った。米国務省歴史局は会期を11月28日から12月1日と記す。戦争をどう終えるか、その後の世界をどう扱うかが同じ交渉の場にあった。今日の国境を一つの会談の結果に縮める前に、決定の段階を見る必要がある。", "href": "2026-11-28-tehran-map-before-border-ja.html"}}, "zh": {"briefing": {"title": "11月28日晨间简报：市场反弹，家庭开支压力仍在", "intro": "韩国和美国股市反弹，但家庭可支配收入并没有同步增长。政治焦点仍是改革落实、党内处分和最高法院院长弹劾时间表。周六早晨，须把昨日收盘和今天安排、已作决定和政治诉求分开阅读。", "href": "2026-11-28-morning-briefing-zh.html"}, "history": {"title": "1943年11月28日，谈判先于地图移动", "intro": "1943年11月28日，罗斯福、丘吉尔、斯大林在德黑兰会面。美国国务院历史办公室将会议日期记为11月28日至12月1日。如何结束战争、如何安排战后世界，被放在同一张谈判桌上。在把今日边界浓缩成一次会议的结果之前，需要看清决策的不同阶段。", "href": "2026-11-28-tehran-map-before-border-zh.html"}}, "es": {"briefing": {"title": "Resumen del 28 de noviembre: rebotan los mercados, persisten los costes familiares", "intro": "Las bolsas coreanas y estadounidenses rebotaron, pero la renta disponible de los hogares no aumentó con ellas. La política sigue centrada en aplicar reformas, las sanciones internas y el calendario propuesto para una destitución judicial. Este sábado conviene separar los cierres de ayer de los planes de hoy, y las decisiones de las exigencias.", "href": "2026-11-28-morning-briefing-es.html"}, "history": {"title": "28 de noviembre de 1943: la negociación se movió antes que el mapa", "intro": "Roosevelt, Churchill y Stalin se reunieron en Teherán el 28 de noviembre de 1943. La Oficina del Historiador de Estados Unidos fecha la conferencia entre ese día y el 1 de diciembre. Cómo terminar la guerra y cómo organizar el mundo posterior compartieron mesa. Antes de reducir las fronteras actuales a una reunión, conviene distinguir las fases de decisión.", "href": "2026-11-28-tehran-map-before-border-es.html"}}};let last='';function sync(){const l=document.documentElement.dataset.lang||'ko';if(last===l)return;last=l;const q=D[l]||D.en;for(const [id,k] of [['daily-news-briefing','briefing'],['president-series-feature','history']]){const e=document.getElementById(id);if(!e)continue;const a=e.querySelector('h2 a');if(a){a.textContent=q[k].title;a.href=q[k].href}e.querySelectorAll('a').forEach(a=>{a.href=q[k].href;if(!a.closest('h2'))a.textContent=({ko:'전문 읽기 →',en:'Read full article →',ja:'全文を読む →',zh:'阅读全文 →',es:'Leer texto completo →'})[l]||'Read full article →';});const p=e.querySelector('p');if(p)p.textContent=q[k].intro;if(k==='briefing'){const m=e.querySelector('div');if(m)m.textContent=({ko:'아침 브리핑',en:'Morning briefing',ja:'朝のブリーフィング',zh:'晨间简报',es:'Resumen de la mañana'})[l]+' · 2026.11.28 · 06:15 KST';}}}new MutationObserver(sync).observe(document.documentElement,{attributes:true,attributeFilter:['data-lang']});sync();})();